-- Migration V3: Seller Storefront Template & Customization System

-- 1. Create seller_storefront table
CREATE TABLE IF NOT EXISTS "seller_storefront" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "seller_id" BIGINT NOT NULL UNIQUE,
    "slug" VARCHAR(100) NOT NULL UNIQUE,
    "store_name" VARCHAR(120) NOT NULL,
    "tagline" VARCHAR(255),
    "logo_url" TEXT,
    "hero_image_url" TEXT,
    "hero_title" VARCHAR(255),
    "hero_subtitle" TEXT,
    "template_id" VARCHAR(30) NOT NULL DEFAULT 'EDITORIAL',
    "theme_mode" VARCHAR(20) NOT NULL DEFAULT 'LIGHT',
    "accent_color" VARCHAR(20) DEFAULT '#B58A56',
    "font_preset" VARCHAR(30) NOT NULL DEFAULT 'ELEGANT',
    "show_featured_products" BOOLEAN NOT NULL DEFAULT TRUE,
    "show_reviews" BOOLEAN NOT NULL DEFAULT TRUE,
    "show_about_section" BOOLEAN NOT NULL DEFAULT FALSE,
    "about_title" VARCHAR(255),
    "about_text" TEXT,
    "about_image_url" TEXT,
    "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    CONSTRAINT "fk_seller_storefront_seller" FOREIGN KEY ("seller_id") REFERENCES "users"("id") ON DELETE CASCADE
);

-- 2. Create seller_storefront_featured_product join table
CREATE TABLE IF NOT EXISTS "seller_storefront_featured_product" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "storefront_id" BIGINT NOT NULL,
    "product_id" BIGINT NOT NULL,
    "position" INT NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "fk_featured_storefront" FOREIGN KEY ("storefront_id") REFERENCES "seller_storefront"("id") ON DELETE CASCADE,
    CONSTRAINT "fk_featured_product" FOREIGN KEY ("product_id") REFERENCES "product"("id") ON DELETE CASCADE,
    CONSTRAINT "uq_storefront_product" UNIQUE ("storefront_id", "product_id")
);

-- 3. Indexes for fast query lookup
CREATE INDEX IF NOT EXISTS "idx_seller_storefront_slug" ON "seller_storefront"("slug");
CREATE INDEX IF NOT EXISTS "idx_seller_storefront_seller" ON "seller_storefront"("seller_id");
CREATE INDEX IF NOT EXISTS "idx_featured_storefront_pos" ON "seller_storefront_featured_product"("storefront_id", "position");

-- 4. Seed default storefronts for existing sellers
INSERT INTO "seller_storefront" (
    "seller_id",
    "slug",
    "store_name",
    "tagline",
    "hero_title",
    "hero_subtitle",
    "template_id",
    "theme_mode",
    "accent_color",
    "font_preset",
    "show_featured_products",
    "show_reviews",
    "show_about_section",
    "created_at",
    "updated_at"
)
SELECT 
    u."id",
    LOWER(REGEXP_REPLACE(u."username", '[^a-zA-Z0-9]+', '-', 'g')),
    u."username" || ' Atelier',
    'Handcrafted fine jewelry made with intention',
    'Timeless pieces for every story',
    'Discover our handcrafted collection designed to elevate your everyday moments.',
    'EDITORIAL',
    'LIGHT',
    '#B58A56',
    'ELEGANT',
    TRUE,
    TRUE,
    FALSE,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM "users" u
WHERE u."role" IN ('SELLER', 'ADMIN')
ON CONFLICT ("seller_id") DO NOTHING;
